// Тикет #6a86f7ed9d38 F-92 (6a86f7ed9d38b8e55508d699) — עבר QA 13.10.2026: загрузка MP3 ВНУТРИ приложения (iPhone, TestFlight 1.0.0 (19), аккаунт клиента).
// Факт 13.10 (скрины 6a86f7ed9d38-ios-b19-mp3-uploaded-pending.png, -mp3-approved.png, -user-recording-available.png, -user-recording-playing.png):
//  профиль → «ממשק ניהול התוכן» → «בורא פרי העץ · נוסח אשכנז…» → «1, בורא פרי העץ…» («עריכת קטע»);
//  без «מי הקליט» → «יש לכתוב מי הקליט לפני ההעלאה.»; «מי הקליט» = «QA test» → «העלאת קובץ MP3» → Files («Недавние») → arvit-ashk-k3.mp3 →
//  «הקובץ arvit-ashk-k3.mp3 הועלה. ההקראה תוצע למשתמשים רק אחרי אישור.», «ממתינה לאישור — המשתמשים עדיין לא שומעים אותה.»,
//  «הוקלט על ידי QA test · הועלה על ידי מנהל תוכן, <дата>» → «אישור ההקראה ופרסומה» → «אושרה על ידי מנהל תוכן, … — מוצעת להשמעה למשתמשים.» →
//  у пользователя («ברכות» → «בורא פרי העץ», נוסח אשכנז) «הקראה: QA test · אושרה על ידי מנהל תוכן», «השמע» активна → «השהה» →
//  уборка: «הסרת ההקראה» → окно «להסיר את ההקראה?» → «הסרת ההקראה» → «ההקראה הוסרה.».
// Отличие от ad-07 (ערבית «המעריב ערבים», проверка «לא תואמת» после правки текста): здесь путь, проверенный 13.10, без правки текста.
// Файл: Android — кладётся автоматически (pushFile в Download); iOS — arvit-ashk-k3.mp3 должен лежать на телефоне в «Файлы»
// (из .qa/research/rec-pages/), выбор в системном пикере — @manual-check, если автоматический тап не нашёл файл (тест ждёт до 3 минут).
// @data @cleanup: в finally запись удаляется («הסרת ההקראה»), файл с Android удаляется, аккаунт — USER1.
import fs from 'node:fs';
import { driver, expect } from '@wdio/globals';
import { byText, byTextContains, byTextMatches, scrollToText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import { playerButton, recordingLine, shown, skipWith } from '../_lib/app-0710.ts';
import {
  asAdmin, backToUser1, openUserHaetz, qaFile, pushToDownloads, removeFromDevice,
  REC_CARD, REC_NONE, REC_UPLOAD_BTN, REC_APPROVE_BTN, REC_APPROVED_RE, setField,
} from '../_lib/admin.ts';
import {
  openAdminHaetzSection, uploadRecordingAny, removeRecordingWithDialog,
  REC_NEED_RECORDER, REC_UPLOADED, REC_PENDING_FULL,
} from '../_lib/app-1310.ts';

const FILE = 'arvit-ashk-k3.mp3';
const RECORDED_BY = 'QA test';

describe('Админка в приложении: загрузка MP3 (F-92)', () => {
  afterEach(async () => { await toHome(); });

  it('AD-10 «בורא פרי העץ» אשכנז: без «מי הקליט» — ошибка; MP3 из системного выбора → «ממתינה לאישור» → утвердить → у пользователя «הקראה: QA test · אושרה…», «השמע»→«השהה» → «הסרת ההקראה» #6a86f7ed9d38 @data @cleanup @manual-check', async function () {
    let remote = '';
    let uploaded = false;
    await asAdmin();
    try {
      if (driver.isAndroid) remote = await pushToDownloads(FILE, fs.readFileSync(qaFile(`research/rec-pages/${FILE}`)).toString('base64'));

      // 0. Исходно записи нет. Есть чужая запись — не трогаем, пропуск.
      await openAdminHaetzSection();
      await scrollToText(REC_CARD);
      if (!(await shown(byTextContains(REC_NONE)))) skipWith(this, 'у «בורא פרי העץ» אשכנז уже есть запись — тест её не трогает');

      // 1. Без «מי הקליט» → «יש לכתוב מי הקליט לפני ההעלאה.» (системный выбор не открывается).
      await setField('מי הקליט', '');
      await (await scrollToText(REC_UPLOAD_BTN)).click();
      await expect(byTextContains(REC_NEED_RECORDER)).toBeDisplayed({ wait: 10000 });

      // 2. «מי הקליט» = «QA test» → «העלאת קובץ MP3» → файл → сообщение о загрузке, «ממתינה לאישור…», «הוקלט על ידי QA test · הועלה על ידי …».
      await uploadRecordingAny(FILE, RECORDED_BY);
      uploaded = true;
      await expect(byTextContains(REC_UPLOADED(FILE))).toBeDisplayed({ wait: 180000 });
      await expect(await scrollToText(REC_PENDING_FULL)).toBeDisplayed();
      await expect(byTextMatches(`(?s).*הוקלט על ידי ${RECORDED_BY} · הועלה על ידי .+`)).toBeDisplayed();

      // 3. «אישור ההקראה ופרסומה» → «אושרה על ידי … — מוצעת להשמעה למשתמשים.».
      await (await scrollToText(REC_APPROVE_BTN)).click();
      await expect(byTextMatches(REC_APPROVED_RE)).toBeDisplayed({ wait: 30000 });

      // 4. Экран пользователя: «ברכות» → «בורא פרי העץ» (אשכנזי): строка записи, «השמע» активна → «השהה» → пауза.
      await openUserHaetz();
      await scrollToText('האזן להקראה');
      await expect(recordingLine()).toHaveText(new RegExp(`הקראה: ${RECORDED_BY} · אושרה על ידי .+`));
      await expect(await playerButton('השמע')).toBeEnabled();
      await (await playerButton('השמע')).click();
      await expect(await playerButton('השהה')).toBeDisplayed({ wait: 10000 });
      await (await playerButton('השהה')).click();
      await expect(await playerButton('השמע')).toBeDisplayed();

      // 5. Уборка: «הסרת ההקראה» → «להסיר את ההקראה?» → «הסרת ההקראה» → «ההקראה הוסרה.».
      await openAdminHaetzSection();
      expect(await removeRecordingWithDialog()).toBe(true);
      uploaded = false;

      // 6. У пользователя записи нет.
      await openUserHaetz();
      await scrollToText('האזן להקראה');
      await expect(recordingLine()).not.toBeDisplayed();
      await expect(byText('השהה')).not.toBeDisplayed();
    } finally {
      try {
        if (remote) await removeFromDevice(remote);
        if (uploaded) {
          await toHome();
          await openAdminHaetzSection();
          await removeRecordingWithDialog();
        }
      } catch (e) {
        console.warn('[AD-10] уборка не прошла — удалить запись вручную: «בורא פרי העץ» אשכנז → «הסרת ההקראה»', e);
      } finally {
        await backToUser1();
      }
    }
  });
});
